// ===============================
// Obtener datos de los nodos
// ===============================
const contactsResponse = $items("Get list of contacts")[0]?.json;
const leadsResponse = $items("Get list of leads")[0]?.json;

// ===============================
// Helpers
// ===============================
function formatDate(timestamp) {
  if (!timestamp) return null;

  const ts = typeof timestamp === 'string' ? parseInt(timestamp) : timestamp;

  if (isNaN(ts) || ts <= 0) return null;

  const date = new Date(ts * 1000);

  if (isNaN(date.getTime())) return null;

  return new Intl.DateTimeFormat('es-ES', {
    timeZone: 'Europe/Madrid',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).format(date);
}

function getCustomField(customFields, fieldCode) {
  if (!Array.isArray(customFields)) return null;

  const field = customFields.find(f => f?.field_code === fieldCode);

  if (field?.values && Array.isArray(field.values) && field.values.length > 0) {
    return field.values[0]?.value ?? field.values[0]?.enum_code ?? field.values[0]?.enum ?? null;
  }

  return null;
}

function getCustomFieldById(customFields, fieldId) {
  if (!Array.isArray(customFields)) return null;

  const field = customFields.find(f => f?.field_id === fieldId);

  if (field?.values && Array.isArray(field.values) && field.values.length > 0) {
    return field.values[0]?.value ?? null;
  }

  return null;
}

// ===============================
// Validación de datos
// ===============================
if (!contactsResponse?._embedded?.contacts?.[0]) {
  return [{
    json: {
      error: 'No se encontró el contacto',
      nombre: null,
      telefono: null,
      email: null,
      dia_de_la_cita: null,
      motivo: null
    }
  }];
}

if (!leadsResponse?._embedded?.leads?.[0]) {
  return [{
    json: {
      error: 'No se encontró el lead',
      nombre: null,
      telefono: null,
      email: null,
      dia_de_la_cita: null,
      motivo: null
    }
  }];
}

// ===============================
// Contacto
// ===============================
const contact = contactsResponse._embedded.contacts[0];

const nombre = contact.name || 'Sin nombre';
const telefono = getCustomField(contact.custom_fields_values, 'PHONE') || 'Sin teléfono';
const email = getCustomField(contact.custom_fields_values, 'EMAIL') || 'Sin email';

// ===============================
// Lead
// ===============================
const lead = leadsResponse._embedded.leads[0];

// Buscar fecha por field_id específico (1864817 = "Dia preferencia cita")
let diaCitaRaw = getCustomFieldById(lead.custom_fields_values, 1864817);

// Fallback a closest_task_at
if (!diaCitaRaw && lead.closest_task_at) {
  diaCitaRaw = lead.closest_task_at;
}

const diaCita = formatDate(diaCitaRaw) || 'Sin cita programada';

// Motivo (añade el field_id correcto si lo tienes)
const motivo = getCustomFieldById(lead.custom_fields_values, 1828342) || 'Sin motivo';

// ===============================
// Output
// ===============================
return [
  {
    json: {
      nombre,
      telefono,
      email,
      dia_de_la_cita: diaCita,
      motivo
    }
  }
];

